def cmp_semver(a, b):
    def is_numeric(s):
        return s.isdigit()

    def parse(v):
        # Remove build metadata
        if '+' in v:
            v = v.split('+')[0]

        # Separate core version and pre-release
        if '-' in v:
            core, pre = v.split('-', 1)
            pre_parts = pre.split('.')
        else:
            core = v
            pre_parts = []

        # Parse major, minor, patch
        parts = core.split('.')
        return int(parts[0]), int(parts[1]), int(parts[2]), pre_parts

    def compare_pre(pre_a, pre_b):
        # A version without pre-release (empty list) sorts AFTER a version with pre-release
        if not pre_a and pre_b:
            return 1
        if pre_a and not pre_b:
            return -1

        # Compare pre-release identifiers
        len_a = len(pre_a)
        len_b = len(pre_b)
        for i in range(max(len_a, len_b)):
            # If one list is exhausted, the shorter list has lower precedence
            if i >= len_a:
                return -1
            if i >= len_b:
                return 1

            str_a = pre_a[i]
            str_b = pre_b[i]

            num_a = is_numeric(str_a)
            num_b = is_numeric(str_b)

            if num_a and num_b:
                # Both numeric
                if int(str_a) != int(str_b):
                    return -1 if int(str_a) < int(str_b) else 1
            elif num_a and not num_b:
                # Numeric < Alphanumeric
                return -1
            elif not num_a and num_b:
                # Alphanumeric > Numeric
                return 1
            else:
                # Both alphanumeric
                if str_a != str_b:
                    return -1 if str_a < str_b else 1
        return 0

    maj_a, min_a, pat_a, pre_a = parse(a)
    maj_b, min_b, pat_b, pre_b = parse(b)

    if maj_a != maj_b: return 1 if maj_a > maj_b else -1
    if min_a != min_b: return 1 if min_a > min_b else -1
    if pat_a != pat_b: return 1 if pat_a > pat_b else -1

    return compare_pre(pre_a, pre_b)
