import heapq

def topk(stream, k):
    heap = []

    for idx, (value, label) in enumerate(stream):
        if len(heap) < k + 1:
            # Store with negative arrival order for correct tie-breaking in min-heap
            heapq.heappush(heap, (value, -idx, label))
        else:
            # Push the new item
            heapq.heappush(heap, (value, -idx, label))
            # Pop the smallest element (lowest value or most recent among ties)
            heapq.heappop(heap)

    # Convert to list sorted by value descending, ties broken by earlier arrival order
    return sorted(heap, key=lambda x: (-x[0], x[1]))
