import heapq
from collections import deque

def window_medians(a, k):
    if k > len(a) or k <= 0:
        return []

    if k == 1:
        return [float(x) for x in a]

    result = []

    left = []  # max heap (stored as negative)
    right = []  # min heap

    removals_left = set()
    removals_right = set()

    def clean_heap(heap, removals):
        while heap and heap[0] in removals:
            heapq.heappop(heap)
            removals.remove(heap[0])

    def get_median():
        clean_heap(left, removals_left)
        clean_heap(right, removals_right)

        # Rebalance after cleaning
        while len(left) > len(right) + 1:
            heapq.heappush(right, -heapq.heappop(left))
            removals_left.discard(-heapq.heappop(left))

        while len(right) > len(left):
            heapq.heappush(left, -heapq.heappop(right))
            removals_right.discard(heapq.heappop(right))

        clean_heap(left, removals_left)
        clean_heap(right, removals_right)

        if len(left) == len(right):
            return float(-left[0] + right[0]) / 2.0
        else:
            return float(-left[0])

    def add_num(num):
        if not left or num <= -left[0]:
            heapq.heappush(left, -num)
        else:
            heapq.heappush(right, num)

        # Rebalance
        if len(left) > len(right) + 1:
            heapq.heappush(right, -heapq.heappop(left))
        elif len(right) > len(left):
            heapq.heappush(left, -heapq.heappop(right))

    def remove_num(num):
        # Mark element for lazy removal based on which heap it's likely in
        if not left:
            if right and num == right[0]:
                removals_right.add(num)
            return
        elif len(left) > len(right):
            if -left[0] == num:
                removals_left.add(-num)
        else:
            if right[0] == num:
                removals_right.add(num)
        # If it might not be at top, mark anyway and clean during get_median
        if -left[0] == num:
            removals_left.add(-num)
        elif right[0] == num:
            removals_right.add(num)

    # Initialize first window
    for num in a[:k]:
        add_num(num)

    result.append(get_median())

    # Slide window
    for i in range(k, len(a)):
        remove_num(a[i-k])
        add_num(a[i])
        result.append(get_median())

    return result
