    def __init__(self):
        self.root = {}

    def add(self, word: str) -> None:
        node = self.root
        for char in word:
            if char not in node:
                node[char] = {}
            node = node[char]
        node['is_word'] = node.get('is_word', 0) + 1

    def remove(self, word: str) -> bool:
