def to_base(n, alphabet):
    if n == 0:
        return alphabet[0]

    is_negative = n < 0
    n = abs(n)
    base = len(alphabet)

    digits = []
    while n > 0:
        digits.append(alphabet[n % base])
        n //= base

    result = ''.join(reversed(digits))
    return '-' + result if is_negative else result

def from_base(s, alphabet):
    if not s:
        raise ValueError("Empty string")

    is_negative = False
    if s[0] == '-':
        is_negative = True
        s = s[1:]
        if not s:
            raise ValueError("Empty string") # Raises for just "-" as well to be robust

    base = len(alphabet)

    # Mapping for O(1) character lookup
    char_map = {char: i for i, char in enumerate(alphabet)}

    value = 0
    for char in s:
        if char not in char_map:
            raise ValueError("Character not in alphabet")
        value = value * base + char_map[char]

    return -value if is_negative else value
