import heapq

def merge_sorted(iterables):
    iterators = [iter(it) for it in iterables]
    heap = []

    # Initialize heap with the first item from each source
    for i, it in enumerate(iterators):
        try:
            item = next(it)
            heapq.heappush(heap, (item, i))
        except StopIteration:
            pass

    # Merge loop
    while heap:
        val, idx = heapq.heappop(heap)
        yield val

        try:
            next_val = next(iterators[idx])
            heapq.heappush(heap, (next_val, idx))
        except StopIteration:
            pass
