const jsonPointer = {
  get: function(doc, pointer) {
    if (typeof pointer !== 'string') {
      throw new TypeError('Pointer must be a string');
    }
    if (pointer !== '' && !pointer.startsWith('/')) {
      throw new Error('Invalid pointer: must be empty or start with /');
    }
    if (pointer === '') return doc;
    const parts = pointer.substring(1).split('/');
    let current = doc;
    for (let i = 0; i < parts.length; i++) {
      if (current == null || typeof current !== 'object') {
        return undefined;
      }
      const key = decode(parts[i]);
      current = current[key];
    }
    return current;
  },
  set: function(doc, pointer, value) {
    if (typeof pointer !== 'string') {
      throw new TypeError('Pointer must be a string');
    }
    if (pointer !== '' && !pointer.startsWith('/')) {
      throw new Error('Invalid pointer: must be empty or start with /');
    }
    if (pointer === '') {
      doc = value;
      return doc;
    }
    if (doc === null || typeof doc !== 'object') {
      doc = {};
    }
    const parts = pointer.substring(1).split('/');
    let current = doc;
    for (let i = 0; i < parts.length - 1; i++) {
      const key = decode(parts[i]);
      if (current[key] === undefined || typeof current[key] !== 'object' || current[key] === null) {
        current[key] = {};
      }
      current = current[key];
    }
    const finalKey = decode(parts[parts.length - 1]);
    if (finalKey === '-') {
      if (!Array.isArray(current)) {
        throw new Error('Cannot append to non-array');
      }
      current.push(value);
    } else {
      current[finalKey] = value;
    }
    return doc;
  }
};

function decode(str) {
  return str.replace(/~1/g, '/').replace(/~0/g, '~');
}

module.exports.jsonPointer = jsonPointer;
