function sqlTag(strings, ...expressions) {
    let textBuffer = strings[0];
    let finalValues = [];
    let currentPlaceholderIndex = 1;
    const placeholderRegex = /\$(\d+)/g;

    function processValue(val, offset) {
        let textPart = '';
        let valuesPart = [];
        let count = 0;

        // Check for inlined sqlTag result (structure {text, values})
        if (typeof val === 'object' && val !== null && 'text' in val && 'values' in val) {
            textPart = val.text.replace(placeholderRegex, (match, num) => {
                return '$' + (parseInt(num) + offset - 1);
            });
            valuesPart = val.values;
            count = valuesPart.length;
        } else if (Array.isArray(val)) {
            let parts = [];
            let offsetAccum = 0;
            for (let item of val) {
                const subRes = processValue(item, offset + offsetAccum);
                parts.push(subRes.text);
                valuesPart.push(...subRes.values);
                offsetAccum += subRes.count;
            }
            textPart = '(' + parts.join(', ') + ')';
            count = offsetAccum;
        } else {
            // Scalar
            textPart = '$' + offset;
            valuesPart = [val];
            count = 1;
        }

        return { text: textPart, values: valuesPart, count };
    }

    for (let i = 0; i < expressions.length; i++) {
        const textPart = strings[i + 1];
        const res = processValue(expressions[i], currentPlaceholderIndex);

        textBuffer += res.text;
        finalValues.push(...res.values);
        currentPlaceholderIndex += res.count;
        textBuffer += textPart;
    }

    return { text: textBuffer, values: finalValues };
}

module.exports = { sqlTag };
