module.exports = function* chunkAsync(source, size) {
    let buffer = [];
    let iterator;

    if (source[Symbol.asyncIterator]) {
        iterator = source[Symbol.asyncIterator]();
    } else if (source[Symbol.iterator]) {
        iterator = source[Symbol.iterator]();
    } else if (typeof source.next === 'function') {
        iterator = source;
    } else {
        throw new TypeError("Source must be an iterable or iterator");
    }

    try {
        while (true) {
            const { done, value } = await iterator.next();
            if (done) break;
            buffer.push(value);
            if (buffer.length >= size) {
                yield buffer.slice(0, size);
                buffer = [];
            }
        }
        if (buffer.length > 0) {
            yield buffer;
        }
    } finally {
        if (iterator && typeof iterator.return === 'function') {
            await iterator.return();
        }
    }
};
