function memoize(fn, keyFn) {
  const objectCache = new WeakMap();
  const mapCache = new Map();
  let calls = 0;

  const wrapper = function(...args) {
    let key;
    let useWeakMap = false;

    if (keyFn) {
      key = keyFn.apply(this, args);
      useWeakMap = false;
    } else {
      if (args.length === 1) {
        const val = args[0];
        if (val !== null && typeof val === 'object') {
          key = val;
          useWeakMap = true;
        } else {
          key = val;
          useWeakMap = false;
        }
      } else {
        // Default fallback for multi-arguments without keyFn
        key = JSON.stringify(args);
        useWeakMap = false;
      }
    }

    let cached;
    if (useWeakMap && objectCache.has(key)) {
      cached = objectCache.get(key);
    } else if (mapCache.has(key)) {
      cached = mapCache.get(key);
    }

    if (cached !== undefined) {
      return cached;
    }

    calls++;

    try {
      const result = fn.apply(this, args);

      if (useWeakMap) {
        objectCache.set(key, result);
      } else {
        mapCache.set(key, result);
      }

      return result;
    } catch (e) {
      throw e;
    }
  };

  // Expose .calls counter via property
  Object.defineProperty(wrapper, 'calls', {
    get: function() { return calls; },
    set: function(val) { calls = val; },
    enumerable: true,
    configurable: true
  });

  // Expose .clear method
  wrapper.clear = function() {
    objectCache.clear();
    mapCache.clear();
  };

  return wrapper;
}

module.exports = memoize;
