module.exports = function toposortTasks(tasks) {
    const taskNames = Object.keys(tasks);
    const taskMap = {};
    for (const name of taskNames) {
        taskMap[name] = tasks[name];
    }

    // Validate dependencies
    for (const [name, task] of Object.entries(taskMap)) {
        for (const dep of task.deps) {
            if (!(dep in taskMap)) {
                return Promise.reject(new Error(`Unknown dependency: ${dep}`));
            }
        }
    }

    const inDegree = new Map();
    const adjList = new Map();
    for (const name of taskNames) {
        inDegree.set(name, 0);
        adjList.set(name, []);
    }

    for (const [name, task] of Object.entries(taskMap)) {
        for (const dep of task.deps) {
            adjList.get(dep).push(name);
            inDegree.set(name, inDegree.get(name) + 1);
        }
    }

    const readyQueue = [];
    for (const name of taskNames) {
        if (inDegree.get(name) === 0) {
            readyQueue.push(name);
        }
    }

    const results = new Map();

    function processPendingTasks() {
        let allReady = false;
        while (readyQueue.length > 0) {
            const name = readyQueue.shift();
            allReady = true;

            const task = taskMap[name];
            const depValues = {};
            for (const dep of task.deps) {
                depValues[dep] = results.get(dep);
            }

            const taskPromise = task.run(depValues);

            taskPromise
                .then(value => {
                    results.set(name, value);
                    for (const dependent of adjList.get(name)) {
                        inDegree.set(dependent, inDegree.get(dependent) - 1);
                        if (inDegree.get(dependent) === 0) {
                            readyQueue.push(dependent);
                        }
                    }
                    processPendingTasks();
                })
                .catch(error => {
                    results.set(name, error);
                    for (const dependent of adjList.get(name)) {
                        inDegree.set(dependent, inDegree.get(dependent) - 1);
                        if (inDegree.get(dependent) === 0) {
                            readyQueue.push(dependent);
                        }
                    }
                    // Propagate error up immediately
                    return Promise.reject(error);
                });
        }

        if (!allReady && readyQueue.length === 0) {
            const unresolved = [];
            for (const name of taskNames) {
                if (!results.has(name)) {
                    unresolved.push(name);
                }
            }
            if (unresolved.length > 0) {
                return Promise.reject(new Error(`Cycle detected involving: ${unresolved.join(', ')}`));
            }
        }
    }

    return processPendingTasks().then(() => {
        return Object.fromEntries(results);
    });
};
