export class Bus<E extends Record<string, unknown>> {
  private handlers = new Map<keyof E, ((data: unknown) => void)[]>()

  public on<K extends keyof E>(
    k: K,
    fn: E[K] extends void ? () => void : (data: E[K]) => void
  ): () => void {
    const list = this.handlers.get(k)
    if (!list) {
      this.handlers.set(k, [fn])
      return () => {
        const arr = this.handlers.get(k)
        if (arr && arr[0] === fn) {
          arr.shift()
          if (arr.length === 0) {
            this.handlers.delete(k)
          }
        }
        return () => {}
      }
    }
    list.push(fn)
    return () => {
      const index = list.indexOf(fn)
      if (index !== -1) {
        list.splice(index, 1)
      }
      return () => {}
    }
  }

  // Overloads to enforce argument requirements based on payload type
  emit<K extends keyof E>(k: K): void
  emit<K extends keyof E>(k: K, payload: E[K]): void

  public emit<K extends keyof E>(
    k: K,
    payload?: E[K] | undefined
  ): void {
    const handlers = this.handlers.get(k)
    if (handlers) {
      handlers.forEach(fn => {
        // Check if handler expects arguments by checking its length property
        // () => void has length 0, (data: T) => void has length 1
        if ((fn as any).length === 0) {
          fn()
        } else {
          fn(payload)
        }
      })
    }
  }
}
