export function pick<T, K extends keyof T>(obj: T, keys: K[]): Pick<T, K> {
    // Runtime check ensures keys are in obj and type safety ensures keys exist on T
    const result: any = {};
    for (const key of keys) {
        // Only copy own properties that are present at runtime
        if (key in obj && obj.hasOwnProperty ? obj.hasOwnProperty(key) : false) {
            (result as any)[key] = obj[key];
        }
    }
    return result as Pick<T, K>;
}

export function omit<T, K extends keyof T>(obj: T, keys: K[]): Omit<T, K> {
    // Copy everything else except excluded keys
    const result: any = {};
    const excludeSet = new Set(keys);
    for (const key in obj) {
        if (Object.prototype.hasOwnProperty.call(obj, key) && !excludeSet.has(key)) {
            (result as any)[key] = obj[key];
        }
    }
    return result as Omit<T, K>;
}
