type DeepPartial<T> = {
    [K in keyof T]:
        T[K] extends (...args: any[]) => any
            ? T[K]
            : T[K] extends readonly any[] | any[]
                ? T[K]
                : T[K] extends object
                    ? DeepPartial<T[K]>
                    : T[K]
};

export function applyPatch<T>(base: T, patch: DeepPartial<T>): T {
    const result = {} as any;

    // Iterate over keys of base to preserve structure and merge
    for (const key in base) {
        if (Object.prototype.hasOwnProperty.call(base, key)) {
            const baseVal = base[key];
            const patchVal = patch[key];

            if (patchVal === undefined) {
                // Explicit undefined or missing key in patch implies "leave alone"
                // Since we are iterating keys of base, if key not in patch, we keep baseVal.
                // If key is in patch but value is explicitly undefined, we keep baseVal.
                result[key] = baseVal;
            } else {
                // Check if both are objects (non-array) to recurse
                if (
                    typeof baseVal === 'object' &&
                    typeof patchVal === 'object' &&
                    baseVal !== null &&
                    patchVal !== null &&
                    !Array.isArray(baseVal) &&
                    !Array.isArray(patchVal)
                ) {
                    result[key] = applyPatch(baseVal, patchVal);
                } else if (Array.isArray(baseVal) && Array.isArray(patchVal)) {
                    // Replace arrays wholesale
                    result[key] = patchVal;
                } else {
                    // Primitives or mixed types
                    result[key] = patchVal;
                }
            }
        }
    }

    // Return the new object typed as T
    return result as T;
}
